<?php
$pageTitle='Projects'; require_once 'includes/auth.php'; require_auth(); $u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('INSERT INTO projects(company_id,name,description,goals,bottlenecks,status,created_by) VALUES(?,?,?,?,?,?,?)');$s->execute([$u['company_id'],trim($_POST['name']),trim($_POST['description']),trim($_POST['goals']),trim($_POST['bottlenecks']),$_POST['status'],$u['id']]);flash('success','Project created successfully.');header('Location: projects.php');exit;}
$s=$pdo->prepare('SELECT p.*,COUNT(t.id) ticket_count FROM projects p LEFT JOIN tickets t ON t.project_id=p.id WHERE p.company_id=? GROUP BY p.id ORDER BY p.created_at DESC');$s->execute([$u['company_id']]);$projects=$s->fetchAll();require 'includes/header.php';
?><div class="section-head"><div><h2>Project organizer</h2><p class="muted">Strategic initiatives and delivery in one place.</p></div><a class="button button-red" href="#new-project">＋ New project</a></div><div class="grid grid-2"><?php foreach($projects as $p): ?><article class="card project-card"><div style="display:flex;justify-content:space-between;gap:10px"><h3><?=e($p['name'])?></h3><span class="badge badge-<?=strtolower(str_replace(' ','-',$p['status']))?>"><?=e($p['status'])?></span></div><p><?=e($p['description'])?></p><div class="project-meta"><div><label>Goals</label><?=e($p['goals']?:'Not defined')?></div><div><label>Bottlenecks</label><?=e($p['bottlenecks']?:'None reported')?></div></div><div class="card-actions"><a class="button button-dark" href="tickets.php?project=<?=$p['id']?>">Manage tickets (<?=$p['ticket_count']?>)</a><a class="button button-light" href="audio.php?project=<?=$p['id']?>">Audio</a></div></article><?php endforeach; ?><?php if(!$projects): ?><div class="card empty">No projects yet.</div><?php endif; ?></div><div id="new-project" class="section-head"><h2>Create a project</h2></div><div class="card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Project name</label><input name="name" required></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>On Hold</option><option>Completed</option></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Goals</label><textarea name="goals"></textarea></div><div class="field"><label>Current bottlenecks</label><textarea name="bottlenecks"></textarea></div></div><div class="form-actions"><button class="button button-red">Create project</button></div></form></div><?php require 'includes/footer.php';
